// Platform administration (Resuto staff console).
// Owner: Agent A (see docs/architecture/MODULE_CONTRACTS.md). Other agents
// import from here but do not edit this file.
import { z } from 'zod';
import { countryCode, isoDateTime, minor } from './common';
import { moduleKey, type ModuleKey } from './modules';

export const PLATFORM_ROLES = ['superadmin', 'support', 'finance'] as const;
export type PlatformRole = (typeof PLATFORM_ROLES)[number];

/**
 * What each platform role may do. Support is read-only; finance reads billing
 * and prices; only superadmins mutate tenants, overrides and prices.
 */
export const PLATFORM_ROLE_CAPABILITIES: Record<PlatformRole, readonly ('tenants:read' | 'billing:read' | 'operations:read' | 'tenants:write' | 'prices:write')[]> = {
  superadmin: ['tenants:read', 'billing:read', 'operations:read', 'tenants:write', 'prices:write'],
  support: ['tenants:read', 'operations:read'],
  finance: ['tenants:read', 'billing:read', 'operations:read'],
};

const reason = z.string().trim().min(3, 'Give a reason (at least 3 characters)').max(500);

export const adminTenantsQuery = z.object({
  q: z.string().trim().max(100).optional(),
  status: z.enum(['onboarding', 'active', 'suspended', 'closed']).optional(),
  plan: z.string().regex(/^[a-z0-9_-]{2,40}$/).optional(),
  country: countryCode.optional(),
  limit: z.coerce.number().int().min(1).max(200).default(50),
  cursor: z.string().max(200).optional(),
});
export type AdminTenantsQuery = z.infer<typeof adminTenantsQuery>;

export const adminStatusChange = z.object({ reason });

export const grantOverride = z.object({
  module: moduleKey,
  enabled: z.boolean().default(true),
  reason,
  expiresAt: isoDateTime,
});
export type GrantOverride = z.infer<typeof grantOverride>;

export const revokeOverride = z.object({ reason });

export const newPlanPrice = z.object({
  planId: z.string().regex(/^[a-z0-9_-]{2,40}$/),
  country: countryCode,
  interval: z.enum(['month', 'year']),
  amountMinor: minor,
  /** Defaults to now. Past dates are rejected: price history is never rewritten. */
  validFrom: isoDateTime.optional(),
});
export type NewPlanPrice = z.infer<typeof newPlanPrice>;

export const newModulePrice = z.object({
  module: moduleKey,
  country: countryCode,
  interval: z.enum(['month', 'year']),
  amountMinor: minor,
  validFrom: isoDateTime.optional(),
});
export type NewModulePrice = z.infer<typeof newModulePrice>;

export interface AdminTenantRow {
  id: string;
  name: string;
  nameAr: string | null;
  slug: string;
  country: 'EG' | 'SA';
  status: string;
  planId: string | null;
  subscriptionStatus: string | null;
  createdAt: string;
  lastOrderAt: string | null;
  counts: { branches: number; members: number; orders30d: number };
}

export interface AdminTenantDetail extends AdminTenantRow {
  timezone: string;
  branches: Array<{ id: string; code: string; name: string; city: string | null; isActive: boolean }>;
  /** Present for superadmin and finance roles only. */
  subscription: null | {
    id: string; planId: string; status: string; interval: string; currentPeriodStart: string; currentPeriodEnd: string;
    trialEndsAt: string | null; graceUntil: string | null; cancelAtPeriodEnd: boolean; pendingPlanId: string | null; addons: ModuleKey[];
    invoices: Array<{ id: string; number: string; status: string; currency: string; totalMinor: number; periodStart: string; periodEnd: string }>;
  };
  billingVisible: boolean;
  overrides: Array<{ id: string; module: ModuleKey; enabled: boolean; reason: string; expiresAt: string | null; active: boolean; createdAt: string }>;
  modules: Record<string, boolean>;
  /** Status and health only — credentials are never returned. */
  integrations: Array<{ id: string; provider: string; category: string; environment: string; status: string; health: Record<string, unknown>; lastHealthCheckAt: string | null; lastError: string | null; connectedAt: string | null }>;
  recentAudit: Array<{ id: number; actorType: string; action: string; entityType: string | null; source: string; createdAt: string }>;
}

export interface AdminOperations {
  generatedAt: string;
  outbox: { unpublished: number; oldestUnpublishedAt: string | null; retrying: number };
  /** stuck = handler runs still 'running' after their lease ended (the worker stopped); replayable like dead letters. */
  eventHandlings: { failed: number; dead: number; stuck: number; recent: Array<{ eventId: string; handler: string; status: string; attempts: number; lastError: string | null; eventType: string; orgId: string | null; updatedAt: string }> };
  webhooks: { failed: number; rejected: number; recent: Array<{ id: string; provider: string; status: string; attempts: number; error: string | null; orgId: string | null; receivedAt: string }> };
  jobs: Array<{ id: number; job: string; status: string; startedAt: string; finishedAt: string | null; error: string | null; stats: Record<string, unknown> }>;
  usage30d: Array<{ metric: string; quantity: number; tenants: number }>;
}

export interface AdminPriceRow {
  id: string;
  key: string;
  country: 'EG' | 'SA';
  currency: 'EGP' | 'SAR';
  interval: 'month' | 'year';
  amountMinor: number;
  active: boolean;
  validFrom: string;
  /** True for the row quotes currently use. */
  current: boolean;
}

export interface AdminPrices {
  plans: AdminPriceRow[];
  modules: AdminPriceRow[];
}
